const $ = s => document.querySelector(s);
const key = 'thien-menh-kingdom-v2';
let state = kingdomInitial(), view = 'city', selectedBuilding = null, selectedNode = 'camp1', heroFocus = 'zhaoyun', results = [], mapView = null, filter = 'Tất cả';
let selectedRegionEntity='home',selectedMailId=null,mailTab='reports';
let campaignChapter=0,realmDraft='shu',selectedRealmCity=null;
let vipPreview=null,bagTab='resources',bagPageIndex=0,gearResults=[],petResults=[];
let selectedFormationSlot=null,gradeFilter='all',roleFilter='all';
let migrated = false, drawerOpen = false, trainingType = 'shield', speed = 1, resultDismissed = false;
try {
  const stored = localStorage.getItem(key) || localStorage.getItem('thien-menh-studio-v1');
  if (stored) { const parsed = JSON.parse(stored); state = migrateKingdom(parsed); migrated = parsed.version === 1; }
} catch {}
const fmt = n => Math.floor(n).toLocaleString('vi-VN');
function sprite(id) { const i=characterById[id].artIndex;if(i>=56)return `--sx:${(i-56)*25}%;--sy:0%;background-size:500% 200%`;if(i<8)return `--sx:${i%4*100/3}%;--sy:${i<4?0:100}%;background-size:400% 200%`;const n=(i-8)%24;return `--sx:${n%6*100/5}%;--sy:${Math.floor(n/6)*100/3}%;background-size:600% 400%`; }
function portrait(id,cls=''){const h=characterById[id],sheet=h.artIndex<8?'':h.artIndex<32?'sheet-a':h.artIndex<56?'sheet-b':'sheet-celestial';return `<span class="hero-art ${sheet} ${cls}" style="${sprite(id)}" role="img" aria-label="Pixel ${h.name}"></span>`;}
function notify(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(notify.timer); notify.timer = setTimeout(() => $('#toast').classList.remove('show'), 4000); }
function save() { try { localStorage.setItem(key, JSON.stringify(durableSave(state))); } catch { notify('Không thể lưu tự động. Dùng Studio → Xuất bản lưu để giữ tiến độ.'); } }
function gameBusy(){return Boolean(state.march||state.worldAI?.expedition||state.battle&&!state.battle.winner);}
function assertIdle() { if(state.worldAI?.expedition)throw new Error('Chờ đội khu vực trở về trước.');if (state.battle&&!state.battle.winner)throw new Error('Hoàn tất trận đang chạy trước khi thay đổi đội.');if (state.march) throw new Error('Chờ đội hành quân về thành trước khi đổi tướng, linh long hoặc thông số.'); }
const resourceName = { food: 'Lương thực', wood: 'Gỗ', stone: 'Đá' };
function priceText(price) { return Object.entries(price).map(([k, v]) => `${fmt(v)} ${resourceName[k]}`).join(' · '); }
function resonancePanel() {
  const r = elementalResonance(state.team), active = activeBonds(state.team);
  return `<div class="resonance"><span>◈ CỘNG HƯỞNG</span><strong>${r.element ? `${r.element} · +${Math.round(r.bonus * 100)}% HP & ATK` : '3 tướng cùng hệ: +10% HP & ATK'}</strong></div>${active.length ? active.map(b => `<div class="bond-chip">⛓ ${b.name}</div>`).join('') : '<p class="muted tiny">Ghép tướng liên quan để mở cộng hưởng điển tích.</p>'}`;
}
function marchbar() {
  const m = state.march, phase = m ? { marching: 'Đang hành quân', combat: 'Đang giao chiến', gathering: 'Đang thu thập', returning: 'Đang trở về' }[m.stage] : 'Sẵn sàng xuất chinh';
  return `<div class="march-title"><span class="eyebrow">ĐẠO QUÂN 01</span><b>${phase}${state.paused && m ? ' · TẠM DỪNG' : ''}</b><small>${m ? `${m.units} quân · ${m.stage === 'combat' ? `${state.battle.clock}s` : `${Math.ceil(m.duration - m.progress)}s`}` : `${state.troops} quân dự bị`}</small>${m ? `<button class="mini-button" data-pause>${state.paused ? '▶ Tiếp tục' : 'Ⅱ Tạm dừng'}</button>` : ''}</div><div class="march-team">${Array.from({ length: 4 }, (_, i) => state.team[i] ? `<button data-view="heroes" title="${heroes.find(h => h.id === state.team[i]).name}">${portrait(state.team[i])}<small>${heroes.find(h => h.id === state.team[i]).name}</small></button>` : '<button data-view="heroes" class="empty-team">＋</button>').join('')}</div><div class="march-bonds">${resonancePanel()}</div><button class="gold-button" data-view="${view === 'city' ? 'world' : 'heroes'}">${view === 'city' ? 'Bản đồ thế giới ↗' : 'Đổi đội hình ↗'}</button>`;
}
function troopSelection() {
  return `<div class="troop-types">${Object.entries(troopTypes).map(([type,t])=>`<button data-army-type="${type}" class="${state.troopType===type?'chosen':''}" ${state.march?'disabled':''} style="--troop:${t.color}"><span>${t.icon}</span><b>${t.name} · Lv.${troopStats(state,type).level}</b><small>${state.regiments[type]} quân</small><em>${t.text}</em></button>`).join('')}</div>`;
}
function buildingPanel() {
  const b=structures.find(b=>b.id===(selectedBuilding||'hall')),level=state.levels[b.id],price=upgradePrice(state,b.id),job=state.construction;
  const canUpgrade=!job&&level<5&&(b.id==='hall'||level<state.levels.hall)&&Object.entries(price).every(([k,v])=>state.resources[k]>=v);
  return `<div class="panel-heading"><span class="eyebrow">CÔNG TRÌNH</span><span class="pill">CẤP ${level}</span></div><div class="building-emblem" style="--accent:${b.color}">${b.id==='barracks'?troopTypes[trainingType].icon:b.icon}</div><h2 id="panel-title">${b.id==='barracks'?'Doanh trại '+troopTypes[trainingType].name:b.name}</h2><p>${b.text}</p>${job?.id===b.id?`<div class="training"><b>Đang nâng lên cấp ${job.target}</b><p>Còn ${Math.max(0,Math.ceil((job.endsAt-Date.now())/1000))} giây</p><button class="gold-button full" data-speedup ${state.coins<50?'disabled':''}>Hoàn tất ngay · ◈ 50</button></div>`:level<5?`<div class="cost-box"><small>NÂNG LÊN CẤP ${level+1} · ${8+level*4} GIÂY</small><p>${priceText(price)}</p></div><button class="gold-button full" data-upgrade="${b.id}" ${canUpgrade?'':'disabled'}>↑ Nâng cấp ${job?'· Thợ đang bận':b.id!=='hall'&&level>=state.levels.hall?'· Cần Đại điện cao hơn':''}</button>`:'<div class="success-note">Công trình đã đạt cấp 5.</div>'}
  ${b.id==='barracks'?`<section class="subpanel"><h3>Huấn luyện ${troopTypes[trainingType].name}</h3><p>20 quân · 160 lương · 80 gỗ · ${Math.max(4,14-state.levels.barracks*2)} giây</p><p>Đang có: <b>${state.regiments[trainingType]}</b> ${troopTypes[trainingType].name}. ${troopTypes[trainingType].text}.</p>${state.training?`<div class="training">${troopTypes[state.training.type||'shield'].name} · còn ${Math.max(0,Math.ceil((state.training.endsAt-Date.now())/1000))} giây</div>`:`<button class="gold-button full" data-train ${state.troops>980||state.resources.food<160||state.resources.wood<80?'disabled':''}>Huấn luyện 20 quân</button>`}<button class="outline-button full" data-army-type="${trainingType}" ${state.march?'disabled':''}>Chọn cho đạo quân xuất chinh</button><p class="muted tiny">Binh chủng cấp ${troopStats(state,trainingType).level}, tự theo cấp người chơi. <button class="text-button" data-view="army">Xem bảng chỉ số binh chủng</button> Các doanh trại dùng chung cấp công trình và một hàng đợi huấn luyện.</p></section>`:''}
  ${b.id==='dragon'?`<section class="subpanel"><h3>Linh long hỗ trợ</h3><p>Mỗi 10 giây giao chiến: Hỏa gây sát thương; Thủy hồi HP; Mộc tạo khiên.</p><div class="dragon-options">${['Hỏa','Thủy','Mộc'].map(e=>`<button data-dragon="${e}" class="${state.dragon===e?'chosen':''}" ${state.march?'disabled':''}>✧ ${e}</button>`).join('')}</div></section>`:''}
  <section class="subpanel"><h3>Công trình trong thành</h3><div class="building-list">${citySites.map(site=>`<button data-building="${site.id}" ${site.type?`data-variant="${site.type}"`:''}><span>${site.type?'⚑ '+troopTypes[site.type].name:structures.find(b=>b.id===site.id).name}</span><b>${state.levels[site.id]}</b></button>`).join('')}</div></section>`;
}
function unitRow(unit, enemy = false) {
  const s = skills[unit.id], b = state.battle, recent = b.events.findLast(e => e.actor === unit.id && e.side === unit.side && b.clock - e.at < 1);
  return `<div class="combat-unit ${unit.hp <= 0 ? 'fallen' : ''} ${recent ? `casting fx-${s.fx}` : ''}">${portrait(unit.id)}<div class="unit-main"><b>${unit.name}</b><div class="unit-bars"><meter value="${unit.hp}" max="${unit.maxHp}" aria-label="Sinh lực ${unit.name}"></meter><span>${Math.ceil(unit.hp)} / ${unit.maxHp}${unit.shield ? ` · Khiên ${unit.shield}` : ''}</span>${!enemy ? `<progress value="${unit.energy}" max="100" aria-label="Nộ khí ${unit.name}"></progress>` : ''}</div><div class="status-line">${unit.burn ? '🔥 Thiêu đốt ' : ''}${unit.marked ? '◉ Thiên nhãn ' : ''}${unit.stun ? '★ Choáng ' : ''}${unit.slow?'↓ Chậm ':''}${unit.manaLock?'M↓ Hồi mana chậm ':''}${unit.immune>0?'⛨ Miễn sát thương ':''}${unit.invincible>0?'✧ Vô địch ':''}${unit.boost ? '↑ Công ' : ''}${unit.exposed ? '↓ Giáp' : ''}</div></div>${!enemy ? `<button class="skill-button ${unit.energy >= 100 ? 'ready' : ''}" data-cast="${unit.key}" title="${s.name}: ${s.text}" ${b.winner || state.paused || unit.hp <= 0 || unit.energy < 100 || unit.stun > 0 ? 'disabled' : ''}><span>${unit.energy >= 100 ? '✦' : unit.energy}</span><small>${s.name}</small></button>` : ''}</div>`;
}
function battleLocation(b){return b.mode==='secret'?{name:secretRealms.find(r=>r.id===b.secretId).bossName}:b.mode==='campaign'?campaignNode(b.stage):b.mode==='bot'?botCities.find(t=>t.id===b.botId):worldNodes.find(t=>t.id===b.nodeId);}
function battlePanel() {
  const b = state.battle, node = battleLocation(b), event = b.events.findLast(e => e.kind !== 'attack' && b.clock - e.at < 2);
  return `<div class="panel-heading"><span class="eyebrow">GIAO CHIẾN · ${b.clock}s / 180s</span><button class="mini-button" data-pause>${state.paused ? '▶ Tiếp tục' : 'Ⅱ Tạm dừng'}</button></div><h2>${b.winner ? b.winner === 'ally' ? 'Chiến thắng!' : b.winner === 'retreat' ? 'Đã rút quân' : 'Thất bại' : node.name}</h2>${b.winner ? `<div class="${b.winner === 'ally' ? 'success-note' : 'warning-note'}">${b.winner === 'ally' ? b.mode==='campaign'?'Đã tự nhận thưởng chiến dịch và mở màn tiếp theo.':'Đã nhận linh ngọc và tài nguyên. Quân sống sót đang trở về.' : 'Quân sống sót đang trở về. Hãy nâng doanh trại, đổi linh long hoặc đội hình.'}</div>` : '<p>Kỹ năng dùng mana hoặc nộ tùy nhân vật; chờ đủ tài nguyên và hết hồi chiêu. Địch luôn tự dùng kỹ năng.</p>'}<div class="damage-summary"><b>Báo cáo sát thương cả trận</b><p>Vật lý: ${b.damageStats?.physical||0} · Phép: ${b.damageStats?.magic||0}<br>Chuẩn: ${b.damageStats?.pure||0}<br>Khiên hấp thụ: ${b.damageStats?.absorbed||0} · Bạo kích: ${b.damageStats?.criticals||0}<br>Chặn: ${fmt(b.damageStats?.blocked||0)} · Phản: ${fmt(b.damageStats?.reflected||0)} · Hồi: ${fmt(b.damageStats?.healing||0)}<br>THẦN: ${b.damageStats?.divine||0} · Buff bị xóa: ${b.damageStats?.dispelled||0}<br>Hồi sinh: ${b.damageStats?.revives||0} · Kết liễu: ${b.damageStats?.executions||0}</p><small>Damage = Công × hệ số × 100/(100+phòng thủ) × lực lượng còn lại × buff/khắc chế; bạo kích ×1,5. Công thức của bản thử.</small></div><div class="battle-enemies">${b.enemies.map(u => unitRow(u, true)).join('')}</div><div class="battle-separator">⚔ ĐỘI VIỄN CHINH ⚔</div><div class="battle-allies">${b.allies.map(u => unitRow(u)).join('')}</div><div class="battle-controls"><button class="outline-button ${state.autoSkill ? 'enabled' : ''}" data-auto aria-pressed="${state.autoSkill}">Tự dùng kỹ năng: ${state.autoSkill ? 'BẬT' : 'TẮT'}</button><span class="dragon-energy">✧ ${state.dragon} long ${b.dragonEnergy}%</span></div>${event ? `<div class="skill-announcement fx-${event.kind}" role="status">${event.text}</div>` : ''}<div class="combat-bonds">${activeBonds(state.team).map(b => `<span>⛓ ${b.name}</span>`).join('')}</div><details class="combat-log"><summary>Nhật ký trận đấu</summary>${b.log.slice(-12).map(l => `<p>${l}</p>`).join('')}</details>${state.march && state.march.stage !== 'returning' ? '<button class="text-button" data-recall>Rút quân về thành</button>' : ''}`;
}
function realmLegend(){return `<div class="realm-legend">${Object.entries(realmFactions).map(([id,f])=>`<span style="--realm:${f.color}">● ${f.name} · ${f.troopName}</span>`).join('')}</div>`;}
function nodePanel() {
  if(state.battle&&state.march?.stage==='combat')return `<h2>Đang giao chiến</h2><button class="gold-button full" data-view="combat">Mở chiến trường</button>`;
  const n = worldNodes.find(n => n.id === selectedNode), m = state.march;
  return `<div class="panel-heading"><span class="eyebrow">THẾ GIỚI / THANH VÂN</span><span class="pill">${n.type === 'camp' ? 'PVE · CẤP ' + n.level : 'TÀI NGUYÊN'}</span></div><div class="location-art ${n.type === 'camp' ? 'enemy-location' : ''}"><span>${n.type === 'camp' ? '⚑' : n.type === 'food' ? '♧' : n.type === 'wood' ? '♠' : n.type === 'home' ? '♜' : '◆'}</span></div><h2>${n.name}</h2><p>${n.type === 'camp' ? 'Đưa 1–9 tướng cùng 60 binh lính đến giao chiến tự động. Phối hợp kỹ năng để phá trận.' : n.type === 'home' ? 'Thành trì của bạn. Xây dựng để phát triển quân lực.' : 'Đưa 60 quân đi thu thập. Nhận 500 ' + resourceName[n.type] + ' sau 20 giây tại điểm này.'}</p>${n.type === 'camp' ? `<div class="enemy-preview">${n.enemies.map(id => portrait(id)).join('')}</div><div class="info-row"><span>Thưởng linh ngọc</span><b>${state.cleared.includes(n.id) ? 60 * n.level : 200 * n.level}</b></div><div class="info-row"><span>Thưởng tài nguyên</span><b>${150 * n.level} lương · ${100 * n.level} gỗ</b></div><small class="muted">Thắng hao hụt 20% quân, thua 50%. Không mất tướng.</small>` : ''}${n.type === 'home' ? '<button class="gold-button full" data-view="city">Về thành trì</button>' : `<button class="gold-button full" data-dispatch="${n.id}" ${m || !state.team.length || state.troops < 60 || state.regiments[state.troopType] < 60 ? 'disabled' : ''}>${n.type === 'camp' ? '⚔ Xuất chinh' : '⚑ Thu thập'} · 60 quân</button>`}${m ? `<div class="march-status"><b>${worldNodes.find(n => n.id === m.nodeId).name}</b><p>${{ marching: 'Đang hành quân', gathering: 'Đang thu thập', combat: 'Đang giao chiến', returning: 'Đang trở về' }[m.stage]} · ${Math.ceil(m.duration - m.progress)} giây</p><button class="outline-button full" data-recall ${m.stage === 'returning' ? 'disabled' : ''}>Gọi quân về</button></div>` : ''}${!m?'<section class="subpanel"><h3>Chọn binh chủng</h3>'+troopSelection()+'</section>':''}<section class="subpanel"><h3>Địa điểm</h3><div class="building-list">${worldNodes.filter(n => n.id !== 'home').map(n => `<button data-node="${n.id}" class="${selectedNode === n.id ? 'chosen' : ''}"><span>${n.type === 'camp' ? '⚑' : '♧'} ${n.name}</span><b>${n.type === 'camp' ? 'Lv.' + n.level : '+500'}</b></button>`).join('')}</div></section><section class="subpanel"><h3>Thành Tam Quốc</h3>${selectedRealmCity?`<p>Đang xem ${realmCities.find(c=>c.id===selectedRealmCity).name} · ${realmFactions[realmCities.find(c=>c.id===selectedRealmCity).faction].name}</p>`:''}<div class="realm-city-list">${realmCities.map(c=>`<button data-realm-city="${c.id}" style="--realm:${realmFactions[c.faction].color}">${c.name}</button>`).join('')}</div></section>`;
}
function queueCards() {
  const job=state.construction,t=state.training,m=state.march;
  return `<button class="queue-item" data-building="${job?.id||'hall'}"><span>⚒</span><div><b>Xây dựng ${job?'1/1':'0/1'}</b><small>${job?structures.find(b=>b.id===job.id).name+' · '+Math.max(0,Math.ceil((job.endsAt-Date.now())/1000))+'s':'Thợ xây sẵn sàng'}</small></div></button><button class="queue-item" data-building="barracks" data-variant="${t?.type||trainingType}"><span>⚑</span><div><b>Huấn luyện ${t?'1/1':'0/1'}</b><small>${t?troopTypes[t.type||'shield'].name+' · '+Math.max(0,Math.ceil((t.endsAt-Date.now())/1000))+'s':state.troops+' quân trong thành'}</small></div></button><button class="queue-item" data-view="${m?.stage==='combat'?'combat':'world'}"><span>♞</span><div><b>${m?{marching:'Đang hành quân',combat:'Đang giao chiến',gathering:'Đang thu thập',returning:'Đang trở về'}[m.stage]:'Đạo quân 0/1'}</b><small>${m?worldNodes.find(n=>n.id===m.nodeId).name:'Sẵn sàng xuất chinh'}</small></div></button>`;
}
function combatCommanderButtons(u,b){const h=characterById[u.id],abilities=u.abilities||h.skills;return `<div class="battle-commander"><button class="combat-skill ${u.canCast?'ready':''} ${u.hp<=0?'fallen':''}" data-cast="${u.key}" data-skill-index="0" title="${h.skills[0].name}: ${describeSkill(h,u.skillLevel)}" ${!u.canCast||b.winner||state.paused?'disabled':''}>${portrait(u.id)}${skillIcon(h.skills[0])}<span class="skill-name">${h.skills[0].name}</span><span class="resource-readout">${u.resourceLabel} ${fmt(u[u.resource])}/${fmt(u.resource==='mana'?u.manaMax:u.rageMax)}</span><progress max="100" value="${u.energy}"></progress><small>${u.canCast?'✦ Dùng chiêu 1':u.cooldown>0?'Hồi '+u.cooldown.toFixed(1)+'s':u.resourceLabel+' '+fmt(u[u.resource])+'/'+u.skillCost}</small></button><div class="battle-extra-skills">${abilities.slice(1).map((ability,n)=>{const i=n+1,ready=u.readySkills?.[i],cd=u.skillCooldowns?.[i]||0;return `<button class="battle-extra-skill ${ready?'ready':''}" data-cast="${u.key}" data-skill-index="${i}" title="${ability.name}: ${describeSkill({...h,skill:ability},u.skillRanks?.[i]||1)} · ${u.skillCosts[i]} ${u.resourceLabel} · Hồi ${cd.toFixed(1)}s" aria-label="${u.name}: ${ability.name}" ${!ready||b.winner||state.paused?'disabled':''}>${skillIcon(ability)}<small>${cd>0?Math.ceil(cd):i+1}</small></button>`;}).join('')}</div></div>`;}
function combatOverlay() {
  const b=state.battle;if(!b)return '';
  const hp=units=>Math.ceil(units.reduce((n,u)=>n+u.hp,0));const last=b.events.findLast(e=>e.kind!=='attack'&&b.clock-e.at<2);
  return `<div class="fight-score"><div><b>THIÊN MỆNH</b><span>${hp(b.allies)} HP · ${troopTypes[b.troopType].name} · Lv.${b.armyLevel||1}</span></div><strong>⚔<small>${Math.floor(b.clock)} / 180s</small></strong><div><b>${battleLocation(b).name.toUpperCase()}</b><span>${hp(b.enemies)} HP · ${troopTypes[b.enemyTroopType]?.name||'Quân địch'}</span></div></div>${last?`<div class="combat-message ${last.kind==='combo'?'is-combo':''}">${last.text}</div>`:''}<div class="combat-bottom"><div class="combat-options"><button data-auto class="${state.autoSkill?'enabled':''}">Tự chiêu ${state.autoSkill?'BẬT':'TẮT'}</button><button data-speed>Tốc độ ×${speed}</button><button data-pause>${state.paused?'▶ Tiếp tục':'Ⅱ Dừng'}</button><button data-recall ${!(state.march||state.worldAI.expedition||b.mode==='secret')||(state.march?.stage||state.worldAI.expedition?.stage)==='returning'?'disabled':''}>Rút quân</button><button data-view="${b.mode==='campaign'?'campaign':(b.mode==='bot'||b.mode==='secret')?'region':'world'}">${b.mode==='campaign'?'Chiến dịch':'Bản đồ'}</button>${b.mode==='campaign'?`<button data-campaign-auto>Tự nối ${state.campaign.autoAdvance?'BẬT':'TẮT'}</button><button data-campaign-stop>Dừng vượt ải</button>`:''}<button data-report>Báo cáo</button></div><div class="skill-dock">${b.allies.map(u=>combatCommanderButtons(u,b)).join('')}<div class="dragon-charge"><span>✧</span><b>${state.dragon} long</b><small>${b.dragonEnergy}% nộ</small></div></div></div>${b.winner&&!resultDismissed?`<div class="combat-result" role="dialog" aria-label="Kết quả trận"><span class="result-crown">${b.winner==='ally'?'♛':'⚑'}</span><h2>${b.winner==='ally'?'Chiến thắng!':b.winner==='retreat'?'Đã rút quân':'Thất bại'}</h2><p>${b.rewardInMail?'Toàn bộ chiến lợi đang chờ nhận trong Hộp thư → Chiến lợi bí cảnh.':b.reward?`◈ ${b.reward.coins} linh ngọc · ${b.reward.food} lương · ${b.reward.wood} gỗ${b.reward.playerXP?' · '+b.reward.playerXP+' EXP quân vương':''}`:b.winner==='ally'?'Đang tổng kết phần thưởng…':'Hãy đổi đội hình, binh chủng hoặc linh long rồi thử lại.'}</p><button class="gold-button" data-result-close>Trở về bản đồ</button><button class="outline-button" data-view="mail" ${b.rewardInMail?'data-open-parcels':''}>${b.rewardInMail?'Nhận chiến lợi trong hộp thư':'Xem phân tích chiến đấu'}</button></div>`:''}`;
}
function mapPage() {
  return `<div class="map-layout"><section class="map-scene"><canvas id="world-map" role="img" aria-label="Thành phố và chiến trường pixel. Có thể kéo, thu phóng và chọn công trình."></canvas>${view==='region'?regionToolbar(state,speed):''}${view!=='combat'?`<div class="account-map-links"><button data-view="profile">♛<small>Hồ sơ</small></button><button data-view="pets">♧<small>Thú cưng</small></button><button data-view="bag">▣<small>Túi đồ</small></button><button data-view="campaign">⚔<small>Vượt ải</small></button><button data-view="mail">✉<small>Chiến tuyến</small></button></div><div class="queue-stack" id="queue-stack">${queueCards()}</div>${view==='world'?realmLegend():''}<div class="city-title" ${view==='region'?'hidden':''}><span>${view==='city'?'THIÊN MỆNH THÀNH':'THANH VÂN ĐẠI LỤC'}</span><small>${view==='city'?'Lãnh địa của bạn':'PvE · '+state.cleared.length+'/3 trại đã chinh phục'}</small></div><div class="event-dock"><button data-view="summon" title="Đài chiêu mộ">✦<small>Chiêu mộ</small></button><button data-building="dragon" title="Điện linh long">✧<small>Linh long</small></button><button data-view="help" title="Hướng dẫn">?<small>Cách chơi</small></button></div><div class="quest-panel"><span>✧</span><div><b>Con đường quân vương</b><p>${state.levels.hall===1?'Nâng Đại điện lên cấp 2':!state.cleared.length?'Chinh phục trại Hoàng Cân':'Kết hợp anh hùng, chinh phục Hổ Lao Quan'}</p></div><button data-view="quests">→</button></div><div class="world-switch"><button data-view="${view==='city'?'world':'city'}" aria-label="${view==='city'?'Mở bản đồ thế giới':'Về thành trì'}">${view==='city'?'⌖':'♜'}</button><small>${view==='city'?'Thế giới':'Thành trì'}</small></div><div class="map-tools"><button data-zoom="-1" aria-label="Thu nhỏ">−</button><button data-center aria-label="Căn giữa">⌖</button><button data-zoom="1" aria-label="Phóng to">＋</button><button data-open-panel>${view==='city'?'Công trình':'Địa điểm'}</button>${view==='world'?'<button data-view="region">Khu vực quanh thành →</button>':''}</div>`:'<div id="combat-overlay">'+combatOverlay()+'</div>'}</section><aside class="detail-panel ${drawerOpen?'is-open':''}" id="details" role="dialog" aria-label="Thông tin công trình và đội quân" ${drawerOpen?'':'hidden'}><button class="close-drawer" data-close-panel aria-label="Đóng thông tin">×</button><div id="panel-content">${drawerOpen?(view==='city'?buildingPanel():view==='combat'?battlePanel():view==='region'?regionPanel(state,selectedRegionEntity):nodePanel()):''}</div></aside></div>`;
}
function heroCard(h,result=false){
 const owned=state.owned.includes(h.id),inTeam=state.team.includes(h.id),stats=getCharacterStats(state,h.id),level=state.heroLevels?.[h.id]||1,skillLevel=state.skillLevels?.[h.id]||1;
 return `<article class="hero-card grade-${h.grade} ${!owned?'unowned':''} ${inTeam?'in-team':''}" data-grade="${h.grade}" data-hero-id="${h.id}" draggable="${owned&&!state.march}" style="--grade:${gradeColors[h.grade]}"><div class="hero-image">${portrait(h.id)}<span class="rarity grade-label grade-${h.grade}" style="color:${gradeColors[h.grade]};border-color:${gradeColors[h.grade]}">${h.grade}</span><span class="element">${h.element} · Lv.${level}</span>${inTeam?'<span class="team-check">✓ Trong trận đồ</span>':''}</div><div class="hero-card-body"><small>${h.vipExclusive?'THÁI SƠ · ĐỘC QUYỀN VIP':h.faction} · ${h.roles.map(r=>archetypeLabels[r]).join(' / ')}</small><h3>${h.name}</h3><div class="hero-stats"><span>⚔ ${stats.physicalAtk}</span><span>✦ ${stats.magicAtk}</span><span>♡ ${stats.maxHp}</span></div><div class="hero-defense">${h.resource==='mana'?'Dùng mana':'Dùng nộ khí'} · Giáp ${stats.armor} · Kháng phép ${stats.resist}</div><h4>✦ ${h.skill.name} · ${skillLevel}/5</h4><p>${describeSkill(h,skillLevel)}</p><small class="myth-weapon">Vũ khí: ${h.weapon}</small>${result?`<div class="result-note">${h.duplicate?'Trùng tướng · +'+(shardYield[h.grade]||0)+' mảnh riêng, +25 ngọc':'Đã sở hữu nhân vật'}</div>`:`<button class="${inTeam?'outline-button enabled':'gold-button'} full" data-team="${h.id}" ${!owned||state.march?'disabled':''}>${!owned?(h.vipExclusive?'Chỉ nhận từ quà VIP':'Chưa sở hữu'):selectedFormationSlot!==null?'Xếp vào ô '+(selectedFormationSlot+1):inTeam?'Rút khỏi đội hình':'Xếp vào trận đồ'}</button>`}<button class="outline-button full" data-inspect="${h.id}">Chi tiết · Cấp độ · Trang bị</button></div></article>`;
}
function formationBoard(){return `<div class="formation-board">${['HÀNG ĐẦU','HÀNG GIỮA','HÀNG SAU'].map((name,row)=>`<div class="formation-row-label">${name}</div>${[0,1,2].map(col=>{const slot=row*3+col,id=state.formation[slot],h=id&&characterById[id];return `<div class="formation-cell ${selectedFormationSlot===slot?'slot-selected':''}" data-slot="${slot}" ${id?`data-drag-hero="${id}" draggable="${!state.march}"`:''}><span class="cell-number">${slot+1}</span>${h?`${portrait(id)}<b>${h.name}</b><small>${h.roles.map(r=>archetypeLabels[r]).join('/')}</small><button class="remove-slot" data-remove-slot="${slot}" title="Rút ${h.name}" ${state.march?'disabled':''}>×</button>`:'<span class="empty-sigil">＋</span>'}<button data-slot-select="${slot}" ${state.march?'disabled':''}>${selectedFormationSlot===slot?'ĐANG CHỌN':'Chọn ô'}</button></div>`;}).join('')}`).join('')}</div>`;}
function heroesPage(){
 const list=heroes.filter(h=>(filter==='Tất cả'||h.faction===filter)&&(gradeFilter==='all'||h.grade===gradeFilter)&&(roleFilter==='all'||h.roles.includes(roleFilter))).slice().sort((a,b)=>gradeOrder.indexOf(a.grade)-gradeOrder.indexOf(b.grade));
 return `<section class="page-title"><div><span class="eyebrow">ĐIỆN ANH HÙNG · ${state.owned.length}/${heroes.length}</span><h1>Trận đồ cửu cung.</h1><p>Xếp tối đa 9 nhân vật vào ba hàng. Kéo thả thẻ hoặc chọn ô rồi bấm Xếp vào trận đồ. Sát thủ ưu tiên hậu tuyến yếu máu.</p></div><button class="gold-button" data-view="summon">Chiêu mộ</button></section><div class="roster-layout"><section class="formation-workbench"><div><span class="eyebrow">ĐỘI HÌNH ${state.team.length}/9 · Ô ${selectedFormationSlot===null?'tự chọn theo vai trò':selectedFormationSlot+1}</span>${formationBoard()}</div><div class="formation-guide">${resonancePanel()}<h3>Vị trí có tác dụng</h3><p>Hàng đầu: đỡ đòn tăng phòng thủ, đấu sĩ tăng công. Hàng giữa: sát thủ tăng chí mạng, pháp sư tăng phép. Hàng sau: cung thủ tăng công và hỗ trợ tăng hồi máu.</p><h3>Mana và nộ khí</h3><p>Mana hồi theo giây; nộ hồi chủ yếu từ đánh thường và chịu đòn. Mỗi tướng chỉ dùng một loại tài nguyên để tung chiêu.</p>${troopSelection()}${state.march?'<div class="warning-note">Đội đang hành quân: tạm khóa đổi người, cấp và trang bị.</div>':''}</div></section><div class="roster-panel"><section class="bonds-grid">${bonds.map(b=>`<details class="bond-card ${activeBonds(state.team).some(a=>a.id===b.id)?'bond-active':''}"><summary><span>⛓ ${b.name}</span><small>${b.ids.map(id=>characterById[id].name).join(' + ')}</small></summary><p>${b.text}</p><p class="lore">${b.lore}</p></details>`).join('')}</section><div class="filter-row">${['Tất cả','Tam Quốc','Tây Du','Phong Thần','Thần Thoại'].map(f=>`<button data-filter="${f}" class="${filter===f?'chosen':''}">${f}</button>`).join('')}<select id="grade-filter" aria-label="Lọc phẩm cấp"><option value="all">Tất cả phẩm cấp</option>${gradeOrder.map(g=>`<option value="${g}" ${gradeFilter===g?'selected':''}>${g}</option>`).join('')}</select><select id="role-filter" aria-label="Lọc vai trò"><option value="all">Tất cả vai trò</option>${Object.entries(archetypeLabels).map(([id,name])=>`<option value="${id}" ${roleFilter===id?'selected':''}>${name}</option>`).join('')}</select><span>${list.length} nhân vật</span></div><div class="heroes-grid">${list.map(h=>heroCard(h)).join('')}</div></div></div>`;
}
function characterPage(){return renderCharacterPage(state,heroFocus,portrait);}
function summonPage() {
  return `<section class="page-title"><div><span class="eyebrow">ĐÀI CHIÊU MỘ</span><h1>Gọi tên người viết lại thiên mệnh.</h1><p>Huyền thoại phương Đông · Tất cả tiền tệ đều là mô phỏng.</p></div></section><section class="summon-stage"><div class="summon-orbit">✦</div><span class="eyebrow">THIÊN ĐỊA ANH HÙNG</span><h2>Một lời triệu gọi. Một huyền thoại.</h2><p>SSR 1% · SSS 3% · SS 6% · S 10% · A 20% · B 25% · C 20% · D 15%<br>5 SSR Thái Sơ chỉ có trong quà VIP, không nằm trong gacha.<br>Thẻ trùng cho mảnh riêng để tăng tối đa 7 sao, kèm 25 ngọc. Bảo hiểm SSR ở lượt thứ 30 chưa ra SSR.</p><div class="pity-bar"><span>Bảo hiểm SSR ${state.pity} / 30</span><progress value="${state.pity}" max="30"></progress></div><div class="ticket-summons"><b>✦ Vé chiêu mộ: ${state.account.bag.summonTicket}</b><button class="gold-button" data-ticket-summon="1" ${state.account.bag.summonTicket<1?'disabled':''}>Dùng 1 vé</button><button class="outline-button" data-ticket-summon="10" ${state.account.bag.summonTicket<10?'disabled':''}>Dùng 10 vé</button></div><div class="summon-buttons"><button class="outline-button" data-summon="1" ${state.coins < 100 ? 'disabled' : ''}>Chiêu mộ ×1 <b>◈ 100</b></button><button class="gold-button" data-summon="10" ${state.coins < 1000 ? 'disabled' : ''}>Chiêu mộ ×10 <b>◈ 1.000</b></button></div></section>${results.length ? `<h2 class="results-heading">Anh hùng đáp lời</h2><div class="heroes-grid">${results.map(h => heroCard(h, true)).join('')}</div>` : ''}`;
}
function studioPage() {
  const h = heroes.find(h => h.id === heroFocus), stat = { ...h, ...state.overrides[h.id] };
  return `<section class="page-title"><div><span class="eyebrow">STUDIO · SANDBOX OFFLINE</span><h1>Xưởng cân bằng vương quốc.</h1><p>Thử đội hình và kỹ năng, chỉnh dữ liệu, sao lưu tiến độ. Không cần kết nối AI khi chơi.</p></div></section><div class="studio-grid"><section class="paper-panel"><span class="eyebrow">CHỈ SỐ TƯỚNG / 01</span><h2>Phòng luyện tướng</h2><form id="editor"><label>Anh hùng<select id="hero-select">${heroes.map(h => `<option value="${h.id}" ${h.id === heroFocus ? 'selected' : ''}>${h.name}</option>`).join('')}</select></label><label>Sinh lực gốc · 50–300<input type="number" name="hp" min="50" max="300" step="1" value="${stat.hp}" required></label><label>Tấn công gốc · 10–80<input type="number" name="atk" min="10" max="80" step="1" value="${stat.atk}" required></label><p>Chỉ số gốc được nhân theo phẩm cấp, cấp độ, trang bị, vị trí và buff trong trận. Thông số áp dụng từ trận mới.</p><button class="gold-button full" ${state.march ? 'disabled' : ''}>Lưu thông số</button></form><button class="text-button" data-reset-card ${state.march ? 'disabled' : ''}>Khôi phục tướng đang chọn</button></section><div class="studio-preview">${heroCard(h, true)}</div><section class="paper-panel"><span class="eyebrow">DỮ LIỆU / 02</span><h2>Thử nghiệm tự do</h2><p>Bản sandbox có thể mở 56 tướng thường (5 SSR Thái Sơ nhận qua quà VIP) để thử mọi kỹ năng và combo. Không cần quay gacha để kiểm tra thiết kế.</p><button class="outline-button full" data-unlock ${state.march ? 'disabled' : ''}>Mở 56 tướng thường để thử nghiệm</button><button class="outline-button full" data-progression-test ${state.march?'disabled':''}>Vật tư phát triển nhân vật</button><button class="outline-button full" data-player-xp>Sandbox: +5.000 EXP người chơi</button><button class="outline-button full" data-player-max>Sandbox: đạt cấp 100 / VIP 15</button><button class="outline-button full" data-reserve-test ${state.march?'disabled':''}>Bổ sung quân để thử nghiệm</button><button class="outline-button full" data-export>↓ Xuất bản lưu JSON</button><label class="file-button">↑ Nhập bản lưu JSON<input type="file" id="import-save" accept=".json,application/json"></label><p>Chỉ lưu tiến độ, tướng, tài nguyên và huấn luyện. Đội đang hành quân được thu hồi khi mở lại bản lưu. Thu nhập khi đóng game tối đa 8 giờ; giao chiến không tự chạy lúc đóng game.</p><button class="text-button" data-reset>Đặt lại toàn bộ tiến độ</button><p class="muted">Đây là game PvE offline độc lập lấy cảm hứng từ dòng xây thành và đội hình nguyên tố; chưa có liên minh, PvP, tài khoản hay thế giới MMO.</p></section></div>`;
}
function helpPage() {
  return `<section class="page-title"><div><span class="eyebrow">HƯỚNG DẪN CHƠI</span><h1>Từ một thành trì đến một huyền thoại.</h1></div></section><div class="guide-grid">${[
    ['01', 'Xây dựng thành trì', 'Chọn công trình trên bản đồ hoặc danh sách. Nâng Đại điện trước, rồi nâng Nông trang, Xưởng gỗ, Mỏ đá để tăng thu nhập. Doanh trại tăng HP; huấn luyện để bổ sung quân.'],
    ['02', 'Lập đội tối đa 9 anh hùng', 'Vào Anh hùng, bỏ hoặc thêm tướng để tối đa 9 ô. Chọn ô hoặc kéo thả vào bàn 3×3: hàng đầu, hàng giữa, hàng sau. Sát thủ ưu tiên hậu tuyến. Ghép Gia Cát Lượng + Triệu Vân để tăng ATK và có đòn phối hợp ngay với bộ tướng ban đầu.'],
    ['03', 'Chọn linh long', 'Chọn Điện linh long trong thành. Hỏa long gây sát thương, Thủy long hồi máu, Mộc long tạo khiên. Long tức kích hoạt mỗi 10 giây giao chiến.'],
    ['04', 'Khám phá thế giới', 'Chọn trại địch để xuất chinh hoặc mỏ tài nguyên để thu thập. Mỗi đội dùng 60 quân. Có 1 đạo quân; hãy chờ quân về trước khi mở chuyến mới.'],
    ['05', 'Kỹ năng và combo', 'Tướng đánh theo tốc độ đánh. Kỹ năng dùng 70% mana hoặc 100% nộ tối đa; cần hết hồi chiêu. Tắt Tự dùng kỹ năng để bấm thủ công và canh combo. Nút Tạm dừng ngừng hành quân/giao chiến; sản xuất tài nguyên vẫn chạy.'],
    ['06', 'Sát thương và phòng thủ', 'Đòn thường dùng công vật lý/giáp; kỹ năng phép dùng pháp công/kháng phép. Giảm sát thương theo 100/(100+phòng thủ). Khắc nguyên tố ×1,25, khắc binh chủng ×1,2, bạo kích ×1,5. Khiên hấp thụ trước HP; lực lượng mất HP thì sát thương giảm. Công thức cân bằng của bản thử.'],
    ['07', 'Binh chủng và hàng đợi', 'Thuẫn khắc Thương, Thương khắc Kỵ, Kỵ khắc Cung, Cung khắc Thuẫn. Chỉ phái đi được khi có 60 quân cùng loại. Có một thợ xây và một hàng đợi huấn luyện; tăng tốc công trình tốn 50 ngọc.'],
    ['08', 'Giữ tiến độ', 'Game tự lưu trên trình duyệt mỗi 5 giây. Vào Studio để xuất/nhập JSON trước khi đổi cách chạy, đổi trình duyệt hoặc đổi máy. Bản lưu cũ v1 được chuyển sang bản mới, giữ tướng và tiền.'],
  ].map(([n, title, text]) => `<section class="paper-panel"><span class="guide-number">${n}</span><h2>${title}</h2><p>${text}</p></section>`).join('')}</div>`;
}
const navigation = [['city', '♜', 'Thành trì'], ['world', '⌖', 'Thế giới'], ['heroes', '♟', 'Anh hùng'], ['summon', '✦', 'Chiêu mộ'], ['studio', '⚒', 'Studio'], ['help', '?', 'Cách chơi']];
function render() {
  mapView?.dispose();mapView=null;
  if(view==='combat'&&!state.battle)view='world';
  const mapMode=['city','world','region','combat'].includes(view);document.body.className=mapMode?('immersive'+(view==='combat'?' in-combat':'')):'panel-mode';
  $('#app').innerHTML=`<header class="game-header"><button class="kingdom-brand" data-view="profile" title="Hồ sơ người chơi"><span class="hud-avatar ${state.account.equipped.frame}">${portrait(state.account.avatar)}</span><span class="lord-level">${playerProgress(state).level}</span><div><b>${escapeAccountText(state.account.name)}</b><small id="power-value">⚔ ${fmt(state.levels.hall*1300+state.troops*10+state.owned.length*120)}</small></div></button><div class="resource-strip">${[['food','♧','Lương'],['wood','♠','Gỗ'],['stone','◆','Đá'],['coins','◈','Ngọc']].map(([id,icon,label])=>`<div class="resource resource-${id}"><span>${icon}</span><div><small>${label}</small><b id="res-${id}">${fmt(id==='coins'?state.coins:state.resources[id])}</b></div></div>`).join('')}</div><button class="hud-mail" data-view="mail" title="Hộp thư chiến tuyến">✉<small id="mail-unread">${state.mailbox.reports.filter(r=>!r.read).length+state.mailbox.notices.filter(n=>!n.read).length+state.mailbox.parcels.filter(p=>!p.claimed).length}</small></button><button class="hud-vip" data-view="vip" title="Đặc quyền và quà VIP">♔<b id="hud-vip-level">VIP ${vipLevel(state)}</b></button><button class="fullscreen-button" data-fullscreen title="Toàn màn hình">⛶</button></header><nav class="game-nav" aria-label="Chức năng game">${navigation.map(([id,icon,title])=>`<button data-view="${id}" class="${(view===id||(view==='character'&&id==='heroes'))?'current':''}"><span>${icon}</span><small>${title}</small></button>`).join('')}</nav><main class="game-content ${mapMode?'map-content':'scroll-content'}">${mapMode?mapPage():accountTabs(view)+({mail:()=>mailPage(state,portrait,selectedMailId,mailTab),inheritance:()=>inheritancePage(state),runes:()=>runesPage(state),quests:()=>questsPage(state),skins:()=>skinsPage(state),army:()=>armyPage(state),campaign:()=>campaignPage(state,campaignChapter),profile:()=>profilePage(state,portrait),vip:()=>vipPage(state,portrait,vipPreview),pets:()=>petsPage(state,petResults),bag:()=>bagPage(state,portrait,bagTab,bagPageIndex),'gear-gacha':()=>renderEquipmentGacha(state,gearResults),heroes:heroesPage,character:characterPage,summon:summonPage,studio:studioPage,help:helpPage})[view]()}</main>${state.account.realm.faction?'':realmSetup(state,realmDraft)}`;
  if($('#world-map'))mapView=mountMap($('#world-map'),()=>({state,view,selected:drawerOpen?(view==='city'?selectedBuilding:selectedNode):null,trainingType}),(id,type)=>{if(view==='city'){selectedBuilding=id;if(type)trainingType=type;}else if(type==='regionEntity'){selectedRegionEntity=id;}else if(type==='realmCity'){selectedRealmCity=id;selectedNode=realmCities.find(c=>c.id===id).node;}else selectedNode=id;drawerOpen=true;refreshLive();});
}
function refreshLive() {
  for(const button of document.querySelectorAll('[data-speed]'))button.textContent='Tốc độ ×'+speed;
  if($('#mail-unread'))$('#mail-unread').textContent=state.mailbox.reports.filter(r=>!r.read).length+state.mailbox.notices.filter(n=>!n.read).length+state.mailbox.parcels.filter(p=>!p.claimed).length;
  for(const button of document.querySelectorAll('[data-time-gift]')){const m=Number(button.dataset.timeGift),done=state.chronicle.claimedTime.includes(m),ready=state.chronicle.onlineSeconds>=m*60;button.disabled=done||!ready;button.textContent=done?'✓ Đã nhận':ready?'Nhận quà':'Còn '+Math.ceil((m*60-state.chronicle.onlineSeconds)/60)+' phút';}
  for(const button of document.querySelectorAll('[data-claim-quest]')){const q=questCatalog.find(q=>q.id===button.dataset.claimQuest),progress=questProgress(state,q),done=state.chronicle.claimedQuests.includes(q.id),ready=progress>=q.target;button.disabled=done||!ready;button.textContent=done?'✓ Đã nhận':ready?'Nhận thưởng':'Đang thực hiện';const row=button.closest('.quest-row');row.classList.toggle('claimable',ready&&!done);row.querySelector('progress').value=progress;const p=row.querySelector('p'),chunks=p.textContent.split(' · ');chunks[0]=fmt(Math.min(progress,q.target))+' / '+fmt(q.target);p.textContent=chunks.join(' · ');}

  for(const id of ['food','wood','stone','coins'])if($(`#res-${id}`))$(`#res-${id}`).textContent=fmt(id==='coins'?state.coins:state.resources[id]);
  for(const el of document.querySelectorAll('[data-bag-resource]')){const id=el.dataset.bagResource,value=id==='coins'?state.coins:id==='essence'?state.essence:id==='vip'?state.account.vipPoints:id==='playerXP'?state.account.totalXP:id==='runePoints'?state.runes.points:state.resources[id];el.textContent=Number(value).toLocaleString('vi-VN',{maximumFractionDigits:3});}
  if($('#power-value'))$('#power-value').textContent='⚔ '+fmt(state.levels.hall*1300+state.troops*10+state.owned.length*120);
  if($('.lord-level'))$('.lord-level').textContent=playerProgress(state).level;if($('#hud-vip-level'))$('#hud-vip-level').textContent='VIP '+vipLevel(state);
  if($('#queue-stack'))$('#queue-stack').innerHTML=queueCards();
  if($('#details')){const portalValue=$('#portal-city')?.value;const logOpen=$('.combat-log')?.open;$('#details').hidden=!drawerOpen;$('#details').classList.toggle('is-open',drawerOpen);if(drawerOpen)$('#panel-content').innerHTML=view==='city'?buildingPanel():view==='combat'?battlePanel():view==='region'?regionPanel(state,selectedRegionEntity):nodePanel();if(portalValue&&$('#portal-city'))$('#portal-city').value=portalValue;if(logOpen&&$('.combat-log'))$('.combat-log').open=true;}
  if($('#combat-overlay'))$('#combat-overlay').innerHTML=combatOverlay();
}
