document.addEventListener('change', async e => {
  if(e.target.hasAttribute('data-manual-equip')){try{state=equipInheritance(state,heroFocus,e.target.value);save();render();}catch(error){notify(error.message);}}
  if(e.target.id==='campaign-chapter'){campaignChapter=Number(e.target.value);render();}
  if(e.target.id==='grade-filter'){gradeFilter=e.target.value;render();}
  if(e.target.id==='role-filter'){roleFilter=e.target.value;render();}
  if(e.target.classList.contains('gear-select')){try{assertIdle();state=equipItem(state,heroFocus,e.target.dataset.gearSlot,e.target.value);save();render();}catch(error){notify(error.message);render();}}
  if (e.target.id === 'hero-select') { heroFocus = e.target.value; render(); }
  if (e.target.id === 'import-save') {
    try { const file = e.target.files[0]; if (!file) return; if (file.size > 10000000) throw new Error('Tệp bản lưu quá lớn.'); const imported = migrateKingdom(JSON.parse(await file.text())); if (!confirm('Thay thế tiến độ hiện tại bằng bản lưu này?')) return; state = imported; results = []; save(); render(); notify('Đã nhập bản lưu.'); }
    catch (error) { notify(error instanceof SyntaxError ? 'Tệp không phải JSON hợp lệ.' : error.message); }
  }
});
document.addEventListener('submit', e => {
  if(e.target.id==='profile-form'||e.target.id==='local-chat-form'){e.preventDefault();try{const data=new FormData(e.target);state=e.target.id==='profile-form'?updateProfile(state,data.get('lordName'),data.get('avatar')):sendLocalMessage(state,data.get('message'));save();render();notify('Đã lưu.');}catch(error){notify(error.message);}return;}
  if (e.target.id !== 'editor') return; e.preventDefault();
  try { assertIdle(); const data = new FormData(e.target), hp = Number(data.get('hp')), atk = Number(data.get('atk')); if (!Number.isInteger(hp) || hp < 50 || hp > 300 || !Number.isInteger(atk) || atk < 10 || atk > 80) throw new Error('HP phải là 50–300; ATK là 10–80, dùng số nguyên.'); state.overrides[heroFocus] = { hp, atk }; save(); render(); notify('Đã lưu thông số cho trận mới.'); }
  catch (error) { notify(error.message); }
});
