if (migrated) notify('Đã chuyển tướng và tiến độ cũ sang vương quốc v5. Đội hình mới gồm 9 ô.');
let previous = performance.now(), saveCounter = 0;
setInterval(() => {
  const now = performance.now(), dt = Math.min(2, (now - previous) / 1000); previous = now;
  const beforeBattleWinner=state.battle?.winner,previousRegion=state.worldAI.expedition?.stage,previousCampaign=state.battle?.stage,before=state.march?.stage;state=economyTick(state);state=state.battle?.mode==='secret'?secretBattleTick(state,dt*speed):state.battle?.mode==='campaign'?campaignTick(state,dt*speed):worldTick(state,dt*speed);state=worldSystemsTick(state,document.visibilityState==='visible'?dt:0,dt*speed);if(previousRegion!=='combat'&&state.worldAI.expedition?.stage==='combat'&&view==='region'){view='combat';drawerOpen=false;resultDismissed=false;render();}if(state.battle?.mode==='campaign'&&state.battle.stage!==previousCampaign){resultDismissed=false;if(view==='combat'||view==='campaign'){view='combat';render();}}if(before!=='combat'&&state.march?.stage==='combat'&&view==='world'){view='combat';drawerOpen=false;resultDismissed=false;render();}else refreshLive();
  if(!beforeBattleWinner&&state.battle?.winner)save();
  if (++saveCounter % 5 === 0) save();
}, 1000);
window.addEventListener('beforeunload',save);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawerOpen){drawerOpen=false;refreshLive();}});

document.addEventListener('dragstart',e=>{const source=e.target.closest('[data-drag-hero],[data-hero-id]');if(!source)return;const id=source.dataset.dragHero||source.dataset.heroId;if(gameBusy()||!state.owned.includes(id)){e.preventDefault();return;}e.dataTransfer.setData('text/plain',id);e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-slot]')&&!gameBusy())e.preventDefault();});
document.addEventListener('drop',e=>{const slot=e.target.closest('[data-slot]');if(!slot)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(gameBusy()||!state.owned.includes(id))return;try{state=assignFormation(state,id,Number(slot.dataset.slot));selectedFormationSlot=null;save();render();}catch(error){notify(error.message);}});
